/* From Uiverse.io by Kemboi-Dun - Tags: simple, minimalist, card, hover */
.__UIV_SCOPE__ .card {
  width: 300px;
  height: 300px;
  background: #e4e3e3da;
  border-radius: 1em;
  display: flex;
  flex-direction: column;
  justify-content: space-evenly;
  gap: 0.4em;
  align-items: flex-start;
  padding: 1em 1.5em;
  transition: all 0.5s ease;
  box-shadow: 0 8px 16px 0 rgba(0,0,0,0.2);
}

.__UIV_SCOPE__ .card:hover {
  background: #f1f1f1;
}

.__UIV_SCOPE__ .card-icon svg {
  height: 4rem;
  width: 4rem;
}

.__UIV_SCOPE__ .card-body {
  text-align: justify;
}
